-- 1. List the number of films per category.

select  f.name, count(fc.film_id) as number_of_films
from film_category as fc
join category as f
on fc.category_id = f.category_id
group by fc.category_id, f.name
order by name asc;


-- 2. Retrieve the store ID, city, and country for each store.
select s.store_id, c.city, co.country
from city as c
join address as ad
on ad.city_id = c.city_id
join store as s
on s.address_id = ad.address_id
join country as co
on co.country_id = c.country_id;


-- 3. Calculate the total revenue generated by each store in dollars.
select sta.store_id, sum(p.amount) as total
from staff as sta
join payment as p
on sta.staff_id = p.staff_id
group by sta.store_id;


-- 4. Determine the average running time of films for each category.

select fc.category_id, avg(f.length)
from film as f
join film_category as fc
on f.film_id = fc.film_id
group by fc.category_id;
